def resolve_models_root() -> Path:
    override = os.environ.get("MEERA_MODELS_ROOT")
    if override and Path(override).expanduser().exists():
        return Path(override).expanduser().resolve()
    # The desktop launcher can start this API from several working
    # directories.  Anchor the bundled model library beside this source file
    # so a restart cannot make already-installed GGUFs disappear.
    source_models = Path(__file__).resolve().parent / "models"
    if source_models.exists():
        return source_models.resolve()
    return Path("./models").resolve()


def read_json_object(path: Path, default: Optional[dict] = None) -> dict:
    if not path.exists():
        return default.copy() if isinstance(default, dict) else {}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        if isinstance(data, dict):
            return data
    except Exception:
        pass
    return default.copy() if isinstance(default, dict) else {}


def write_json_object(path: Path, payload: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")


def sumDirectoryBytes(dir_path: Path) -> int:
    if not dir_path.exists():
        return 0
    total = 0
    for path_obj in dir_path.rglob("*"):
        if path_obj.is_file():
            try:
                total += path_obj.stat().st_size
            except OSError:
                continue
    return total


def safe_slug(value: str) -> str:
    slug = re.sub(r"[^0-9a-zA-Z._-]+", "-", value.strip())
    slug = re.sub(r"-{2,}", "-", slug).strip("-._")
    return slug or "model"


def quant_bits_from_name(value: str) -> Optional[int]:
    match = QUANT_PATTERN.search(value or "")
    if not match:
        return None
    token = match.group(1).upper()
    if token.startswith(("Q2", "IQ2")):
        return 2
    if token.startswith(("Q3", "IQ3")):
        return 3
    if token.startswith(("Q4", "IQ4")):
        return 4
    if token.startswith(("Q5", "IQ5")):
        return 5
    if token.startswith(("Q6", "IQ6")):
        return 6
    if token.startswith("Q8"):
        return 8
    if token in {"F16", "BF16"}:
        return 16
    if token == "F32":
        return 32
    return None


def precision_label_from_name(value: str) -> str:
    bits = quant_bits_from_name(value)
    if bits:
        if bits in {16, 32}:
            return f"{bits}-bit float"
        return f"{bits}-bit quantized"
    lowered = value.lower()
    if "fp16" in lowered or "f16" in lowered or "bf16" in lowered:
        return "FP16"
    if "fp32" in lowered or "f32" in lowered:
        return "FP32"
    return "GGUF"


def humanizeModelLabel(value: str) -> str:
    normalized = re.sub(r"[-_]+", " ", value or "").replace("/", " ").strip()
    normalized = re.sub(r"(?i)(unsloth|local|gguf)", "", normalized)
    normalized = re.sub(r"\s+", " ", normalized).strip()
    return normalized or value or "Local Model"


def inferPurpose(value: str) -> Tuple[str, bool]:
    lowered = (value or "").lower()
    if any(token in lowered for token in ["asr", "speech-to-text", "transcribe"]):
        return "asr", False
    if any(token in lowered for token in ["voice", "tts", "speech"]):
        return "speech", False
    if any(token in lowered for token in ["coder", "code"]):
        return "coding", True
    if any(token in lowered for token in ["math", "reason"]):
        return "math", True
    return "chat", True


def inferDynamicModelId(folder_name: str, repo_id: Optional[str]) -> str:
    import re
    def strip_prefixes(s):
        return re.sub(r'^((local|unsloth|Quantized|TheBloke|lmstudio-community|bartowski|mradermacher|city96)[^a-zA-Z0-9]*)+', '', s, flags=re.IGNORECASE)
    
    if repo_id:
        base = repo_id.split("/")[-1] if "/" in repo_id else repo_id
        return safe_slug(strip_prefixes(base))
    return safe_slug(strip_prefixes(folder_name))


def extractRepoId(config: Optional[dict]) -> Optional[str]:
    if not isinstance(config, dict):
        return None
    for key in ["_name_or_path", "name_or_path", "model_id", "model"]:
        value = config.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    return None


def extractDtype(config: Optional[dict]) -> Optional[str]:
    if not isinstance(config, dict):
        return None
    dtype = config.get("torch_dtype") or config.get("dtype")
    return dtype.strip().lower() if isinstance(dtype, str) and dtype.strip() else None


def extractQuantBits(config: Optional[dict]) -> Optional[int]:
    if not isinstance(config, dict):
        return None
    quant = config.get("quantization_config")
    if isinstance(quant, dict):
        if quant.get("load_in_4bit") is True:
            return 4
        if quant.get("load_in_8bit") is True:
            return 8
        for key in ["bits", "bit_width", "bits_per_weight"]:
            value = quant.get(key)
            if isinstance(value, int) and value in {4, 8}:
                return value
    return None


def extractParamCount(config: Optional[dict]) -> Optional[int]:
    if not isinstance(config, dict):
        return None
    for key in ["num_parameters", "n_params", "params", "parameter_count", "num_params", "model_parameters"]:
        value = config.get(key)
        if isinstance(value, int) and value > 0:
            return int(value)
        if isinstance(value, str) and value.strip().isdigit():
            return int(value.strip())
    return None


def bytesPerParam(config: Optional[dict], quant_bits: Optional[int]) -> Optional[float]:
    if quant_bits in {4, 8}:
        return float(quant_bits) / 8.0
    dtype = extractDtype(config)
    if not dtype:
        return None
    mapping = {
        "float16": 2.0,
        "fp16": 2.0,
        "bfloat16": 2.0,
        "bf16": 2.0,
        "float32": 4.0,
        "fp32": 4.0,
        "float64": 8.0,
        "fp64": 8.0,
        "int8": 1.0,
        "uint8": 1.0,
        "int4": 0.5,
    }
    return mapping.get(dtype)


def formatParamCount(count: int) -> str:
    if count >= 1_000_000_000:
        value = count / 1_000_000_000
        return f"{value:.1f}B" if value < 10 else f"{value:.0f}B"
    if count >= 1_000_000:
        value = count / 1_000_000
        return f"{value:.1f}M" if value < 10 else f"{value:.0f}M"
    if count >= 1_000:
        return f"{count / 1_000:.1f}K"
    return str(int(count))


def readIndexTotalSize(dir_path: str) -> int:
    for name in ["model.safetensors.index.json", "pytorch_model.bin.index.json"]:
        full_path = Path(dir_path) / name
        data = read_json_object(full_path)
        metadata = data.get("metadata") if isinstance(data, dict) else None
        total_size = None
        if isinstance(metadata, dict):
            total_size = metadata.get("total_size")
        if isinstance(total_size, int) and total_size > 0:
            return total_size
        total_size = data.get("total_size") if isinstance(data, dict) else None
        if isinstance(total_size, int) and total_size > 0:
            return total_size
    return 0


def deriveParamsLabel(config: Optional[dict], weight_bytes: int, size_bytes: int, quant_bits: Optional[int]) -> str:
    explicit = extractParamCount(config)
    if explicit and explicit > 0:
        return formatParamCount(explicit)
    bpp = bytesPerParam(config, quant_bits)
    base = weight_bytes if weight_bytes > 0 else size_bytes
    if bpp and base > 0:
        return formatParamCount(int(base / bpp))
    return ""


def current_hf_token() -> str:
    payload = read_json_object(HF_TOKEN_FILE, {"tokens": []})
    tokens = payload.get("tokens", [])
    if isinstance(tokens, list):
        for token in reversed(tokens):
            if isinstance(token, str) and token.strip():
                return token.strip()
    return ""


def gguf_file_options(model_dir: Path) -> List[dict]:
    options: List[dict] = []
    for file_path in sorted(model_dir.glob("*.gguf"), key=lambda item: item.name.lower()):
        try:
            size = file_path.stat().st_size
        except OSError:
            size = 0
        options.append({
            "filename": file_path.name,
            "size": size,
            "quant_bits": quant_bits_from_name(file_path.name) or 0,
            "precision_label": precision_label_from_name(file_path.name),
        })
    return options


def load_runtime_settings_store() -> dict:
    return read_json_object(MODEL_RUNTIME_SETTINGS_FILE, {"models": {}})


def save_runtime_settings_store(store: dict) -> None:
    write_json_object(MODEL_RUNTIME_SETTINGS_FILE, store)


def scan_local_gguf_library() -> List[dict]:
    root = resolve_models_root()
    if not root.exists():
        return []

    results: List[dict] = []
    for model_dir in sorted([entry for entry in root.iterdir() if entry.is_dir()], key=lambda entry: entry.name.lower()):
        gguf_files = gguf_file_options(model_dir)
        if not gguf_files:
            continue

        config = read_json_object(model_dir / "config.json")
        manifest = read_json_object(model_dir / MODEL_MANIFEST_NAME)
        repo_id = extractRepoId(config) or str(manifest.get("repo_id") or "").strip() or None
        label_source = str(manifest.get("label") or (repo_id.split("/")[-1] if repo_id else model_dir.name))
        label = humanizeModelLabel(label_source)
        model_id = inferDynamicModelId(model_dir.name, repo_id)
        local_bytes = sumDirectoryBytes(model_dir)
        quant_bits = next((file_info["quant_bits"] or None for file_info in gguf_files if file_info.get("quant_bits")), None)
        params = deriveParamsLabel(config, readIndexTotalSize(str(model_dir)), local_bytes, quant_bits)
        purpose, chat_capable = inferPurpose(f"{label} {model_dir.name} {repo_id or ''}")
        
        caps = ["streaming"]
        if chat_capable:
            caps.append("chat")
            name_lower = f"{label} {model_dir.name} {repo_id or ''}".lower()
            if any(t in name_lower for t in ["instruct", "it", "-it", "chat"]):
                caps.append("tools")
            if any(t in name_lower for t in ["vision", "vl", "llava", "pixtral"]):
                caps.append("vision")

        results.append({
            "id": model_id,
            "label": label,
            "capabilities": caps,
            "folder": model_dir.name,
            "present": True,
            "size_bytes": local_bytes,
            "local_bytes": local_bytes,
            "path": str(model_dir),
            "params": params or None,
            "precision": gguf_file_options(model_dir)[0]["precision_label"] if gguf_file_options(model_dir) else "GGUF",
            "repo_id": repo_id,
            "quant_bits": quant_bits,
            "model_type": "causal",
            "purpose": purpose,
            "chat_capable": chat_capable,
            "has_gguf": True,
            "gguf_files": gguf_files,
            "manifest": manifest,
        })

    return results


def lookup_local_model(model_id: str) -> Optional[dict]:
    def _canonical_id(value: object) -> str:
        normalized = re.sub(r"[^a-z0-9]+", "-", str(value or "").lower()).strip("-")
        return normalized.removeprefix("local-")

    requested_id = _canonical_id(model_id)
    for entry in scan_local_gguf_library():
        if entry.get("id") == model_id or entry.get("repo_id") == model_id or entry.get("folder") == model_id:
            return entry
        # Older desktop builds stored IDs such as
        # ``local-gemma-4-e2b-it-gguf`` while the disk scanner returns the
        # actual folder ID.  Match a normalized alias so model discovery and
        # model loading always refer to the same installed GGUF.
        if requested_id and any(
            _canonical_id(entry.get(key)) == requested_id
            for key in ("id", "repo_id", "folder", "label")
        ):
            return entry
    return None


