# --- Chat Schemas ---

class ChatMessageContent(BaseModel):
    type: str = "text"
    text: Optional[str] = None
    image_url: Optional[dict] = None

class ChatMessage(BaseModel):
    role: MessageRole = MessageRole.USER
    content: Union[str, List[ChatMessageContent]] = ""
    name: Optional[str] = None
    tool_calls: Optional[List[dict]] = None
    tool_call_id: Optional[str] = None

class ChatAttachmentPayload(BaseModel):
    """A file attached directly to this chat turn from the browser. The
    frontend reads the file client-side and sends its raw bytes as base64
    inline on the chat request â€” it does NOT go through /api/rag/upload.
    This must mirror the frontend's ChatAttachmentPayload type exactly:
    { name, type, size, content_base64 }."""
    name: str = "attachment"
    type: str = ""  # browser-reported MIME type, may be empty/unreliable
    size: int = 0
    content_base64: str = ""


class AttachmentPreviewRequest(BaseModel):
    name: str = "attachment"
    type: str = ""
    size: int = 0
    content_base64: str = ""

class ChatCompletionRequest(BaseModel):
    model: str
    messages: List[ChatMessage]
    temperature: Optional[float] = None
    top_p: Optional[float] = None
    top_k: Optional[int] = None
    max_tokens: Optional[int] = None
    stream: bool = False
    stop: Optional[Union[str, List[str]]] = None
    frequency_penalty: Optional[float] = None
    presence_penalty: Optional[float] = None
    repetition_penalty: Optional[float] = None
    tools: Optional[List[dict]] = None
    tool_choice: Optional[Union[str, dict]] = None
    response_format: Optional[dict] = None
    seed: Optional[int] = None
    inference_mode: Optional[InferenceMode] = None
    provider: Optional[str] = None
    conversation_id: Optional[str] = None
    user_context: Optional[dict] = None
    use_rag: bool = False
    use_mcp: bool = True
    enable_image_search: bool = True
    enable_file_tools: bool = True
    enable_screen_tools: bool = True
    allow_screen_control: bool = False
    use_web_grounding: Optional[bool] = None  # None = auto-detect via intent
    rag_top_k: int = 5
    document_ids: Optional[List[str]] = None  # RAG documents attached to THIS turn â€”
        # full text is injected directly (no similarity search), and auto web
        # grounding is skipped for the turn unless use_web_grounding is explicit.
    attachments: Optional[List[ChatAttachmentPayload]] = None  # Files attached
        # inline as base64 straight from the browser for THIS turn (this is
        # what the actual chat UI sends â€” see ChatAttachmentPayload). Handled
        # the same way as document_ids: read directly and injected as real
        # file content, no web search, no RAG similarity search.

    user_integrations: Optional[List[str]] = None

    skip_terminal_autoexec: bool = False
    # Internal-only flag, never set by any real client request. Set to True
    # exclusively by helper calls that invoke chat_completion() on themselves
    # purely to generate short text (e.g. _explain_terminal_result_llm) --
    # NOT to have another turn of the actual conversation. Without this,
    # such a call re-enters the COPILOT-TERMINAL pre-exec block below with
    # a synthetic "user message" that echoes the very command/goal text
    # that triggered the original detection, matches the same intent
    # keyword again, re-executes the same command, generates another
    # explanation, which calls chat_completion again -- an unbounded
    # self-triggering loop that repeats the same command roughly once per
    # round trip, exactly what showed up as endless repeated
    # [COPILOT-TERMINAL] log lines with no chat message ever sent by the user.

class ToolCall(BaseModel):
    id: str
    type: str = "function"
    function: dict

class DeltaContent(BaseModel):
    role: Optional[str] = None
    content: Optional[str] = None
