# SECTION 5: PARAMETER RESOLVER
# â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

class ParameterResolver:
    """
    Resolves inference parameters with priority:
    1. User-specified (manual) â€“ highest
    2. Model-specific defaults
    3. Provider-specific defaults
    4. Global defaults â€“ lowest
    """

    MODEL_DEFAULTS: Dict[str, dict] = {
        "claude": {"temperature": 1.0, "top_p": 0.9, "max_tokens": 8192},
        "gpt-4": {"temperature": 0.7, "top_p": 1.0, "max_tokens": 8192},
        "gpt-3.5": {"temperature": 0.7, "top_p": 1.0, "max_tokens": 4096},
        "gemini": {"temperature": 1.0, "top_p": 0.95, "max_tokens": 8192},
        "llama": {"temperature": 0.7, "top_p": 0.9, "top_k": 40, "max_tokens": 4096},
        "mistral": {"temperature": 0.7, "top_p": 0.9, "top_k": 40, "max_tokens": 4096},
        "qwen": {"temperature": 0.7, "top_p": 0.9, "top_k": 40, "max_tokens": 8192},
        "deepseek": {"temperature": 0.7, "top_p": 0.9, "top_k": 40, "max_tokens": 8192},
        "phi": {"temperature": 0.6, "top_p": 0.9, "max_tokens": 2048},
        "gemma": {"temperature": 0.7, "top_p": 0.95, "max_tokens": 8192, "repetition_penalty": 1.0},
        "command": {"temperature": 0.7, "top_p": 0.9, "max_tokens": 4096},
    }

    PROVIDER_DEFAULTS: Dict[str, dict] = {
        "anthropic": {"max_tokens": 8192, "temperature": 1.0},
        "google": {"max_tokens": 8192, "temperature": 1.0},
        "openai": {"max_tokens": 4096, "temperature": 0.7},
        "cohere": {"max_tokens": 4096, "temperature": 0.7},
        "ollama": {"top_k": 40, "repetition_penalty": 1.1},
        "lmstudio": {"top_k": 40, "repetition_penalty": 1.1},
    }

    def __init__(self, global_defaults: ParameterDefaults):
        self.global_defaults = global_defaults

    def resolve(self, request: ChatCompletionRequest,
                provider_id: str = "") -> dict:
        """Resolve all parameters into a final dict."""
        base = self.global_defaults.model_dump()

        # Apply provider defaults
        for pid, pdefs in self.PROVIDER_DEFAULTS.items():
            if pid in provider_id.lower():
                for k, v in pdefs.items():
                    if k in base:
                        base[k] = v

        # Apply model defaults
        model_lower = request.model.lower()
        for pattern, mdefs in self.MODEL_DEFAULTS.items():
            if pattern in model_lower:
                for k, v in mdefs.items():
                    if k in base:
                        base[k] = v

        # Apply user-specified overrides (manual takes priority)
        user_overrides = {}
        for field_name in [
            "temperature", "top_p", "top_k", "max_tokens",
            "frequency_penalty", "presence_penalty", "repetition_penalty", "stop"
        ]:
            val = getattr(request, field_name, None)
            if val is not None:
                user_overrides[field_name] = val

        base.update(user_overrides)

        # Clean up None values
        return {k: v for k, v in base.items() if v is not None}


# â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
# SECTION 6: CLOUD INFERENCE ENGINE
# â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

class CloudInferenceEngine:
    """Handles all cloud provider API calls with unified interface."""

    def __init__(self, persistence: PersistenceManager):
        self.persistence = persistence
        self._clients: Dict[str, httpx.AsyncClient] = {}

    def _get_client(self, provider_id: str) -> httpx.AsyncClient:
        if provider_id not in self._clients:
            self._clients[provider_id] = httpx.AsyncClient(
                timeout=httpx.Timeout(1800.0, connect=10.0),
                limits=httpx.Limits(max_connections=20, max_keepalive_connections=5)
            )
        return self._clients[provider_id]

    def _get_provider_info(self, provider_id: str) -> dict:
        config = self.persistence.config
        conn = config.cloud_providers.get(provider_id)
        if not conn:
            raise HTTPException(404, f"Provider '{provider_id}' not configured")
        info = CLOUD_PROVIDERS.get(provider_id, {})
        base_url = conn.base_url or info.get("base_url", "")
        return {
            **info,
            "base_url": base_url,
            "api_key": conn.api_key,
        }

    def _build_headers(self, provider_id: str, info: dict) -> dict:
        headers = {"Content-Type": "application/json"}
        auth_header = info.get("auth_header", "Authorization")
        auth_prefix = info.get("auth_prefix", "Bearer ")
        api_key = info.get("api_key", "")
        if api_key:
            headers[auth_header] = f"{auth_prefix}{api_key}"
        if info.get("version_header"):
            headers[info["version_header"]] = info["version_value"]
        return headers

    async def list_models(self, provider_id: str) -> List[ModelInfo]:
        info = self._get_provider_info(provider_id)
        client = self._get_client(provider_id)
        headers = self._build_headers(provider_id, info)
        endpoint = info.get("models_endpoint", "/models")
        url = f"{info['base_url']}{endpoint}"

        try:
            resp = await client.get(url, headers=headers)
            resp.raise_for_status()
            data = resp.json()
        except Exception as e:
            logger.error(f"Failed to list models for {provider_id}: {e}")
            return []

        models = []
        raw_models = data.get("data", data if isinstance(data, list) else [])
        for m in raw_models:
            mid = m.get("id", m.get("name", ""))
            models.append(ModelInfo(
                id=mid,
                name=m.get("name", mid),
                provider=provider_id,
                owned_by=m.get("owned_by", provider_id),
                is_gguf="gguf" in mid.lower(),
                is_local=False,
                capabilities=self._detect_capabilities(info, m),
            ))
        return models

    def _detect_capabilities(self, info: dict, model_data: dict) -> List[str]:
        caps = ["chat"]
        if info.get("vision"):
            caps.append("vision")
        if info.get("tools"):
            caps.append("tools")
        if info.get("streaming"):
            caps.append("streaming")
        mid = model_data.get("id", "").lower()
        if any(v in mid for v in ["vision", "vl", "img"]):
            if "vision" not in caps:
                caps.append("vision")
        return caps

    async def test_connection(self, provider_id: str) -> Tuple[bool, str, List[str]]:
        """Test provider connection, return (success, error, models)."""
        try:
            models = await self.list_models(provider_id)
            return True, "", [m.id for m in models]
        except Exception as e:
            return False, str(e), []

    async def chat_completion(
        self,
        provider_id: str,
        model: str,
        messages: List[dict],
        params: dict,
        tools: Optional[List[dict]] = None,
        tool_choice: Optional[Union[str, dict]] = None,
        stream: bool = False,
    ) -> AsyncGenerator[str, None] | dict:
        info = self._get_provider_info(provider_id)
        fmt = info.get("format", "openai")

        if fmt == "openai":
            return await self._chat_openai(info, model, messages, params,
                                           tools, tool_choice, stream, provider_id)
        elif fmt == "anthropic":
            return await self._chat_anthropic(info, model, messages, params,
                                              tools, tool_choice, stream, provider_id)
        elif fmt == "google":
            return await self._chat_google(info, model, messages, params,
                                           tools, tool_choice, stream, provider_id)
        elif fmt == "cohere":
            return await self._chat_cohere(info, model, messages, params,
                                           tools, stream, provider_id)
        else:
            raise HTTPException(400, f"Unsupported format: {fmt}")

    async def _chat_openai(self, info, model, messages, params,
                           tools, tool_choice, stream, provider_id):
        client = self._get_client(provider_id)
        headers = self._build_headers(provider_id, info)
        url = f"{info['base_url']}{info['chat_endpoint']}"

        body: dict = {
            "model": model,
            "messages": messages,
            "stream": stream,
        }
        # Add supported params
        param_map = {
            "temperature": "temperature", "top_p": "top_p",
            "max_tokens": "max_tokens", "frequency_penalty": "frequency_penalty",
            "presence_penalty": "presence_penalty", "stop": "stop",
            "seed": "seed", "response_format": "response_format",
        }
        for src, dst in param_map.items():
            if src in params and params[src] is not None:
                body[dst] = params[src]
        if tools:
            body["tools"] = tools
        if tool_choice:
            body["tool_choice"] = tool_choice

        if stream:
            return self._stream_openai(client, url, headers, body)
        else:
            resp = await client.post(url, headers=headers, json=body, timeout=1800)
            resp.raise_for_status()
            return resp.json()

    async def _stream_openai(self, client, url, headers, body):
        async with client.stream("POST", url, headers=headers, json=body,
                                 timeout=1800) as resp:
            resp.raise_for_status()
            async for line in resp.aiter_lines():
                line = line.strip()
                if not line:
                    continue
                if line.startswith("data: "):
                    data = line[6:]
                    if data.strip() == "[DONE]":
                        yield "data: [DONE]\n\n"
                        break
                    try:
                        parsed = json.loads(data)
                        yield f"data: {json.dumps(parsed)}\n\n"
                    except json.JSONDecodeError:
                        continue
                else:
                    try:
                        parsed = json.loads(line)
                        yield f"data: {json.dumps(parsed)}\n\n"
                    except json.JSONDecodeError:
                        continue

    @staticmethod
    def _to_anthropic_content(content):
        """Anthropic's API expects image blocks as {"type": "image", "source":
        {"type": "base64", "media_type": ..., "data": ...}} â€” not the OpenAI-style
        {"type": "image_url", "image_url": {"url": "data:...;base64,..."}} that
        the rest of this codebase builds messages with. Translate here so
        image attachments actually work when Anthropic is the selected provider."""
        if isinstance(content, str) or not isinstance(content, list):
            return content
        blocks = []
        for part in content:
            if not isinstance(part, dict):
                continue
            if part.get("type") == "image_url":
                url = part.get("image_url", {}).get("url", "")
                if url.startswith("data:") and ";base64," in url:
                    mime, b64_data = url[5:].split(";base64,", 1)
                    blocks.append({
                        "type": "image",
                        "source": {"type": "base64", "media_type": mime, "data": b64_data},
                    })
            else:
                blocks.append(part)
        return blocks

    async def _chat_anthropic(self, info, model, messages, params,
                              tools, tool_choice, stream, provider_id):
        client = self._get_client(provider_id)
        headers = self._build_headers(provider_id, info)
        url = f"{info['base_url']}{info['chat_endpoint']}"

        # Convert messages to Anthropic format
        system_msg = ""
        anthropic_msgs = []
        for m in messages:
            if m.get("role") == "system":
                system_msg = m.get("content", "")
                continue
            # â”€â”€ Multi-turn thinking block preservation â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            # If the assistant previously produced thinking blocks (Claude
            # extended thinking with cryptographic signatures), they must
            # be echoed back verbatim or Anthropic returns 400.
            m_thinking_blocks = m.get("thinking_blocks")
            if m.get("role") == "assistant" and isinstance(m_thinking_blocks, list) and m_thinking_blocks:
                blocks = []
                for tb in m_thinking_blocks:
                    if isinstance(tb, dict) and tb.get("type") == "thinking":
                        blk = {"type": "thinking", "thinking": tb["thinking"]}
                        if tb.get("signature"):
                            blk["signature"] = tb["signature"]
                        blocks.append(blk)
                # Append the actual text/tool content after thinking blocks
                content = self._to_anthropic_content(m.get("content", ""))
                if isinstance(content, str):
                    if content:
                        blocks.append({"type": "text", "text": content})
                elif isinstance(content, list):
                    blocks.extend(content)
                # Also include any tool_use blocks
                if m.get("tool_calls"):
                    for tc in m["tool_calls"]:
                        blocks.append({
                            "type": "tool_use",
                            "id": tc["id"],
                            "name": tc["function"]["name"],
                            "input": tc["function"].get("arguments", {}),
                        })
                msg = {"role": "assistant", "content": blocks if blocks else ""}
                anthropic_msgs.append(msg)
                continue

            msg = {"role": m["role"], "content": self._to_anthropic_content(m.get("content", ""))}
            if m.get("tool_calls"):
                blocks = []
                for tc in m["tool_calls"]:
                    blocks.append({
                        "type": "tool_use",
                        "id": tc["id"],
                        "name": tc["function"]["name"],
                        "input": tc["function"].get("arguments", {}),
                    })
                msg["content"] = blocks
            elif m.get("role") == "tool":
                msg = {
                    "role": "user",
                    "content": [{
                        "type": "tool_result",
                        "tool_use_id": m.get("tool_call_id", ""),
                        "content": m.get("content", ""),
                    }]
                }
            anthropic_msgs.append(msg)

        # Determine whether to enable extended thinking for this Claude model.
        # Claude 3.7+ and Claude 4+ support extended thinking. When enabled,
        # the model produces a dedicated thinking content block *before* its
        # visible reply, streamed via separate content_block_delta events
        # with delta.type == "thinking_delta".  We request a generous token
        # budget so the model can reason deeply without being cut short.
        _model_lower = model.lower()
        _supports_extended_thinking = any(
            tag in _model_lower
            for tag in ("claude-3.7", "claude-4", "claude-sonnet-4", "claude-opus-4")
        )
        _thinking_enabled = _supports_extended_thinking and stream

        base_max_tokens = int(params.get("max_tokens") or 16000)
        # When extended thinking is on, Anthropic requires max_tokens to be
        # large enough to cover *both* thinking + output tokens.  We bump it
        # to at least 16k thinking + the original output budget.
        if _thinking_enabled:
            effective_max = max(16000 + base_max_tokens, 32768)
        else:
            effective_max = base_max_tokens

        body: dict = {
            "model": model,
            "messages": anthropic_msgs,
            "max_tokens": effective_max,
            "stream": stream,
        }
        if _thinking_enabled:
            body["thinking"] = {"type": "enabled", "budget_tokens": min(16000, effective_max - base_max_tokens)}
            # Anthropic requires temperature=1 when thinking is enabled.
            body.pop("temperature", None)
        if system_msg:
            body["system"] = system_msg
        if "temperature" in params and not _thinking_enabled:
            body["temperature"] = params["temperature"]
        if "top_p" in params:
            body["top_p"] = params["top_p"]
        if "top_k" in params:
            body["top_k"] = params["top_k"]

        # Convert tools to Anthropic format
        if tools:
            anthropic_tools = []
            for t in tools:
                if t.get("type") == "function":
                    anthropic_tools.append({
                        "name": t["function"]["name"],
                        "description": t["function"].get("description", ""),
                        "input_schema": t["function"].get("parameters", {}),
                    })
            if anthropic_tools:
                body["tools"] = anthropic_tools
        if tool_choice:
            if isinstance(tool_choice, str) and tool_choice == "auto":
                body["tool_choice"] = {"type": "auto"}
            elif isinstance(tool_choice, dict):
                body["tool_choice"] = {"type": "tool", "name": tool_choice.get("function", {}).get("name", "")}

        if stream:
            return self._stream_anthropic(client, url, headers, body)
        else:
            resp = await client.post(url, headers=headers, json=body, timeout=1800)
            resp.raise_for_status()
            return self._convert_anthropic_response(resp.json(), model)

    async def _stream_anthropic(self, client, url, headers, body):
        """Stream Anthropic responses, properly handling extended thinking.

        Claude 3.7+ / 4+ with extended thinking enabled emits:
          - message_start
          - content_block_start  (type: "thinking" | "text" | "tool_use")
          - content_block_delta  (delta.type: "thinking_delta" | "text_delta" | "input_json_delta" | "signature_delta")
          - content_block_stop
          - message_delta
          - message_stop

        We yield proper SSE lifecycle events so the frontend can render a
        genuine, token-by-token thinking block:
          event: thinking_start   â€” first reasoning token is about to arrive
          event: thinking         â€” each reasoning chunk (existing event name)
          event: thinking_end     â€” reasoning finished, visible answer next
          data: {...}             â€” OpenAI-format text/tool chunks (unchanged)
        """
        _thinking_started = False
        _current_block_type = None  # "thinking" | "text" | "tool_use" | None
        _msg_id = ""
        # Accumulate thinking blocks for multi-turn signature preservation.
        # Claude signs every thinking block; subsequent turns must echo them
        # back verbatim or Anthropic rejects the request with 400.
        _accumulated_thinking_blocks: list = []
        _current_thinking_text = ""
        _current_thinking_signature = ""

        def _thinking_start_sse(msg_id: str) -> str:
            return f"event: thinking_start\ndata: {json.dumps({'id': msg_id, 'started_at': int(time.time() * 1000)}, ensure_ascii=False)}\n\n"

        def _thinking_end_sse(msg_id: str, duration_ms: int = 0) -> str:
            return f"event: thinking_end\ndata: {json.dumps({'id': msg_id, 'duration_ms': duration_ms}, ensure_ascii=False)}\n\n"

        def _thinking_delta_sse(text: str) -> str:
            return f"event: thinking\ndata: {json.dumps({'chunk': text}, ensure_ascii=False)}\n\n"

        _thinking_first_token_at: Optional[float] = None

        async with client.stream("POST", url, headers=headers, json=body,
                                 timeout=1800) as resp:
            resp.raise_for_status()
            async for line in resp.aiter_lines():
                line = line.strip()
                if not line or not line.startswith("data: "):
                    continue
                data = line[6:]
                try:
                    event = json.loads(data)
                except json.JSONDecodeError:
                    continue
                evt_type = event.get("type", "")

                # â”€â”€ message_start: capture the message id â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                if evt_type == "message_start":
                    _msg_id = event.get("message", {}).get("id", "")
                    # Yield the role chunk so downstream sees the assistant role
                    chunk = self._convert_anthropic_stream_chunk(event, body.get("model", ""))
                    if chunk:
                        yield f"data: {json.dumps(chunk)}\n\n"
                    continue

                # â”€â”€ content_block_start: detect thinking vs text vs tool â”€
                if evt_type == "content_block_start":
                    block = event.get("content_block", {})
                    _current_block_type = block.get("type", "")

                    if _current_block_type == "thinking":
                        # Claude is about to stream its internal reasoning.
                        _thinking_first_token_at = time.time()
                        yield _thinking_start_sse(_msg_id)
                    else:
                        # text or tool_use block starting â€” if we were in a
                        # thinking block that never got a proper stop (shouldn't
                        # happen but be defensive), close it now.
                        if _thinking_started and _current_block_type == "text":
                            duration = int((time.time() - _thinking_first_token_at) * 1000) if _thinking_first_token_at else 0
                            yield _thinking_end_sse(_msg_id, duration)
                            _thinking_started = False
                    continue

                # â”€â”€ content_block_delta: the actual streamed tokens â”€â”€â”€â”€â”€â”€â”€
                if evt_type == "content_block_delta":
                    delta = event.get("delta", {})
                    delta_type = delta.get("type", "")

                    if delta_type == "thinking_delta":
                        # â”€â”€ This is the real model reasoning stream â”€â”€â”€â”€â”€â”€â”€
                        thinking_text = delta.get("thinking", "")
                        if thinking_text:
                            _thinking_started = True
                            _current_thinking_text += thinking_text
                            yield _thinking_delta_sse(thinking_text)
                        continue

                    if delta_type == "signature_delta":
                        # Cryptographic signature for thinking block integrity.
                        # Accumulate it â€” we must echo the full block (text +
                        # signature) back to Claude in subsequent turns.
                        _current_thinking_signature += delta.get("signature", "")
                        continue

                    # text_delta and input_json_delta: convert normally
                    chunk = self._convert_anthropic_stream_chunk(event, body.get("model", ""))
                    if chunk:
                        yield f"data: {json.dumps(chunk)}\n\n"
                    continue

                # â”€â”€ content_block_stop: close the current block â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                if evt_type == "content_block_stop":
                    if _current_block_type == "thinking" and _thinking_started:
                        duration = int((time.time() - _thinking_first_token_at) * 1000) if _thinking_first_token_at else 0
                        yield _thinking_end_sse(_msg_id, duration)
                        _thinking_started = False
                        # Finalize the thinking block for multi-turn echo.
                        if _current_thinking_text:
                            block: dict = {
                                "type": "thinking",
                                "thinking": _current_thinking_text,
                            }
                            if _current_thinking_signature:
                                block["signature"] = _current_thinking_signature
                            _accumulated_thinking_blocks.append(block)
                        _current_thinking_text = ""
                        _current_thinking_signature = ""
                    _current_block_type = None
                    continue

                # â”€â”€ message_delta: stop_reason â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                if evt_type == "message_delta":
                    chunk = self._convert_anthropic_stream_chunk(event, body.get("model", ""))
                    if chunk:
                        yield f"data: {json.dumps(chunk)}\n\n"
                    continue

                # â”€â”€ message_stop: done â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                if evt_type == "message_stop":
                    # Defensive: if a thinking block is still open, close it.
                    if _thinking_started:
                        duration = int((time.time() - _thinking_first_token_at) * 1000) if _thinking_first_token_at else 0
                        yield _thinking_end_sse(_msg_id, duration)
                        _thinking_started = False
                        # Also finalize any dangling thinking block
                        if _current_thinking_text:
                            block: dict = {
                                "type": "thinking",
                                "thinking": _current_thinking_text,
                            }
                            if _current_thinking_signature:
                                block["signature"] = _current_thinking_signature
                            _accumulated_thinking_blocks.append(block)
                            _current_thinking_text = ""
                            _current_thinking_signature = ""
                    # Emit accumulated thinking blocks for multi-turn
                    # signature preservation.  The frontend stores these and
                    # sends them back on the next request so Claude sees its
                    # own signed thinking blocks in the conversation history.
                    if _accumulated_thinking_blocks:
                        yield (
                            "event: thinking_blocks\ndata: "
                            + json.dumps({"blocks": _accumulated_thinking_blocks}, ensure_ascii=False)
                            + "\n\n"
                        )
                    yield "data: [DONE]\n\n"
                    break

    def _convert_anthropic_response(self, resp, model):
        content = resp.get("content", [])
        text_parts = []
        tool_calls = []
        for block in content:
            if block.get("type") == "text":
                text_parts.append(block["text"])
            elif block.get("type") == "tool_use":
                tool_calls.append({
                    "id": block["id"],
                    "type": "function",
                    "function": {
                        "name": block["name"],
                        "arguments": json.dumps(block.get("input", {})),
                    }
                })
        msg = {"role": "assistant", "content": "\n".join(text_parts)}
        if tool_calls:
            msg["tool_calls"] = tool_calls
        return {
            "id": resp.get("id", f"chatcmpl-{uuid.uuid4().hex[:12]}"),
            "object": "chat.completion",
            "created": int(time.time()),
            "model": model,
            "choices": [{
                "index": 0, "message": msg,
                "finish_reason": "tool_calls" if tool_calls else resp.get("stop_reason", "stop")
            }],
            "usage": {
                "prompt_tokens": resp.get("usage", {}).get("input_tokens", 0),
                "completion_tokens": resp.get("usage", {}).get("output_tokens", 0),
                "total_tokens": resp.get("usage", {}).get("input_tokens", 0) +
                                resp.get("usage", {}).get("output_tokens", 0),
            }
        }

    def _convert_anthropic_stream_chunk(self, event, model):
        evt_type = event.get("type", "")
        chunk_id = event.get("message", {}).get("id", f"chatcmpl-{uuid.uuid4().hex[:12]}")

        if evt_type == "content_block_delta":
            delta = event.get("delta", {})
            if delta.get("type") == "text_delta":
                return {
                    "id": chunk_id, "object": "chat.completion.chunk",
                    "created": int(time.time()), "model": model,
                    "choices": [{
                        "index": 0,
                        "delta": {"content": delta.get("text", "")},
                        "finish_reason": None
                    }]
                }
            elif delta.get("type") == "input_json_delta":
                return None  # Tool call streaming - simplified
        elif evt_type == "message_start":
            return {
                "id": chunk_id, "object": "chat.completion.chunk",
                "created": int(time.time()), "model": model,
                "choices": [{"index": 0, "delta": {"role": "assistant"}, "finish_reason": None}]
            }
        elif evt_type == "message_delta":
            return {
                "id": chunk_id, "object": "chat.completion.chunk",
                "created": int(time.time()), "model": model,
                "choices": [{"index": 0, "delta": {}, "finish_reason": event.get("delta", {}).get("stop_reason", "stop")}]
            }
        return None

    async def _chat_google(self, info, model, messages, params,
                           tools, tool_choice, stream, provider_id):
        client = self._get_client(provider_id)
        headers = self._build_headers(provider_id, info)
        api_key = info.get("api_key", "")
        url = f"{info['base_url']}/models/{model}:generateContent?key={api_key}"
        if stream:
            url = f"{info['base_url']}/models/{model}:streamGenerateContent?key={api_key}&alt=sse"

        # Convert messages to Google format
        system_instruction = None
        contents = []
        for m in messages:
            if m.get("role") == "system":
                system_instruction = {"parts": [{"text": m.get("content", "")}]}
                continue
            role = "user" if m["role"] == "user" else "model"
            parts = []
            content = m.get("content", "")
            if isinstance(content, str):
                parts.append({"text": content})
            elif isinstance(content, list):
                for c in content:
                    if isinstance(c, dict):
                        if c.get("type") == "text":
                            parts.append({"text": c.get("text", "")})
                        elif c.get("type") == "image_url":
                            img_url = c.get("image_url", {}).get("url", "")
                            if img_url.startswith("data:"):
                                b64 = img_url.split(",", 1)[1]
                                mime = img_url.split(";")[0].split(":")[1]
                                parts.append({"inlineData": {"mimeType": mime, "data": b64}})
            if m.get("tool_calls"):
                for tc in m["tool_calls"]:
                    parts.append({
                        "functionCall": {
                            "name": tc["function"]["name"],
                            "args": tc["function"].get("arguments", {}),
                        }
                    })
            elif m.get("role") == "tool":
                parts.append({
                    "functionResponse": {
                        "name": m.get("name", ""),
                        "response": {"content": m.get("content", "")},
                    }
                })
                role = "function"
            if parts:
                contents.append({"role": role, "parts": parts})

        body: dict = {"contents": contents}
        if system_instruction:
            body["systemInstruction"] = system_instruction
        gen_config = {}
        if "temperature" in params:
            gen_config["temperature"] = params["temperature"]
        if "top_p" in params:
            gen_config["topP"] = params["top_p"]
        if "top_k" in params:
            gen_config["topK"] = params["top_k"]
        if "max_tokens" in params:
            gen_config["maxOutputTokens"] = params["max_tokens"]
        if gen_config:
            body["generationConfig"] = gen_config

        if tools:
            google_tools = []
            for t in tools:
                if t.get("type") == "function":
                    google_tools.append({
                        "functionDeclarations": [{
                            "name": t["function"]["name"],
                            "description": t["function"].get("description", ""),
                            "parameters": t["function"].get("parameters", {}),
                        }]
                    })
            if google_tools:
                body["tools"] = google_tools

        if stream:
            return self._stream_google(client, url, headers, body, model)
        else:
            resp = await client.post(url, headers=headers, json=body, timeout=1800)
            resp.raise_for_status()
            return self._convert_google_response(resp.json(), model)

    async def _stream_google(self, client, url, headers, body, model):
        async with client.stream("POST", url, headers=headers, json=body,
                                 timeout=1800) as resp:
            resp.raise_for_status()
            async for line in resp.aiter_lines():
                line = line.strip()
                if not line or not line.startswith("data: "):
                    continue
                data = line[6:]
                try:
                    event = json.loads(data)
                    chunk = self._convert_google_stream_chunk(event, model)
                    if chunk:
                        yield f"data: {json.dumps(chunk)}\n\n"
                except json.JSONDecodeError:
                    continue
            yield "data: [DONE]\n\n"

    def _convert_google_response(self, resp, model):
        candidates = resp.get("candidates", [])
        if not candidates:
            return {"choices": [], "model": model}
        cand = candidates[0]
        parts = cand.get("content", {}).get("parts", [])
        text = ""
        tool_calls = []
        for p in parts:
            if "text" in p:
                text += p["text"]
            elif "functionCall" in p:
                fc = p["functionCall"]
                tool_calls.append({
                    "id": f"call_{uuid.uuid4().hex[:12]}",
                    "type": "function",
                    "function": {
                        "name": fc["name"],
                        "arguments": json.dumps(fc.get("args", {})),
                    }
                })
        msg = {"role": "assistant", "content": text}
        if tool_calls:
            msg["tool_calls"] = tool_calls
        usage = resp.get("usageMetadata", {})
        return {
            "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
            "object": "chat.completion",
            "created": int(time.time()),
            "model": model,
            "choices": [{
                "index": 0, "message": msg,
                "finish_reason": "tool_calls" if tool_calls else cand.get("finishReason", "stop").lower()
            }],
            "usage": {
                "prompt_tokens": usage.get("promptTokenCount", 0),
                "completion_tokens": usage.get("candidatesTokenCount", 0),
                "total_tokens": usage.get("totalTokenCount", 0),
            }
        }

    def _convert_google_stream_chunk(self, event, model):
        """Convert a Google Gemini streaming chunk.

        Gemini 2.5 Pro/Flash may include thought parts (reasoning) marked
        with ``thought: true``.  We route these into the ``reasoning``
        delta field so the _stream_with_tools loop picks them up and
        forwards as thinking events â€” exactly like OpenAI o-series.
        """
        candidates = event.get("candidates", [])
        if not candidates:
            return None
        cand = candidates[0]
        parts = cand.get("content", {}).get("parts", [])
        text = ""
        reasoning = ""
        for p in parts:
            if p.get("thought"):
                # Gemini's thought part â€” this is the model reasoning.
                reasoning += p.get("text", "")
            elif "text" in p:
                text += p["text"]

        delta: dict = {}
        if text:
            delta["content"] = text
        if reasoning:
            delta["reasoning"] = reasoning

        return {
            "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
            "object": "chat.completion.chunk",
            "created": int(time.time()),
            "model": model,
            "choices": [{
                "index": 0,
                "delta": delta,
                "finish_reason": cand.get("finishReason", None)
            }]
        }

    async def _chat_cohere(self, info, model, messages, params,
                           tools, stream, provider_id):
        client = self._get_client(provider_id)
        headers = self._build_headers(provider_id, info)
        url = f"{info['base_url']}{info['chat_endpoint']}"

        chat_history = []
        last_message = ""
        for m in messages:
            if m["role"] == "system":
                continue
            if m["role"] == "user":
                last_message = m.get("content", "") if isinstance(m.get("content"), str) else str(m.get("content", ""))
            else:
                chat_history.append({
                    "role": "USER" if m["role"] == "user" else "CHATBOT",
                    "message": m.get("content", "")
                })

        body = {
            "model": model,
            "message": last_message,
            "chat_history": chat_history,
            "stream": stream,
        }
        if "temperature" in params:
            body["temperature"] = params["temperature"]
        if "top_p" in params:
            body["p"] = params["top_p"]
        if "top_k" in params:
            body["k"] = params["top_k"]
        if "max_tokens" in params:
            body["max_tokens"] = params["max_tokens"]

        if stream:
            return self._stream_cohere(client, url, headers, body, model)
        else:
            resp = await client.post(url, headers=headers, json=body, timeout=1800)
            resp.raise_for_status()
            data = resp.json()
            return {
                "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
                "object": "chat.completion",
                "created": int(time.time()),
                "model": model,
                "choices": [{
                    "index": 0,
                    "message": {"role": "assistant", "content": data.get("text", "")},
                    "finish_reason": "stop"
                }],
                "usage": {
                    "prompt_tokens": data.get("meta", {}).get("billed_units", {}).get("input_tokens", 0),
                    "completion_tokens": data.get("meta", {}).get("billed_units", {}).get("output_tokens", 0),
                    "total_tokens": 0,
                }
            }

    async def _stream_cohere(self, client, url, headers, body, model):
        async with client.stream("POST", url, headers=headers, json=body,
                                 timeout=1800) as resp:
            resp.raise_for_status()
            async for line in resp.aiter_lines():
                line = line.strip()
                if not line:
                    continue
                try:
                    event = json.loads(line)
                    if event.get("event_type") == "text-generation":
                        chunk = {
                            "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
                            "object": "chat.completion.chunk",
                            "created": int(time.time()),
                            "model": model,
                            "choices": [{
                                "index": 0,
                                "delta": {"content": event.get("text", "")},
                                "finish_reason": None
                            }]
                        }
                        yield f"data: {json.dumps(chunk)}\n\n"
                    elif event.get("event_type") == "stream-end":
                        yield "data: [DONE]\n\n"
                        break
                except json.JSONDecodeError:
                    continue

    async def close(self):
        for client in self._clients.values():
            await client.aclose()
        self._clients.clear()


