# SECTION 7: LOCAL INFERENCE ENGINE
# â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

class LocalInferenceEngine:
    """Handles local GGUF inference via LM Studio, Ollama, llama.cpp, KoboldCpp."""

    def __init__(self, persistence: PersistenceManager):
        self.persistence = persistence
        self._clients: Dict[str, httpx.AsyncClient] = {}

    def _get_client(self, provider_id: str) -> httpx.AsyncClient:
        if provider_id not in self._clients:
            self._clients[provider_id] = httpx.AsyncClient(
                timeout=httpx.Timeout(600.0, connect=5.0),
                limits=httpx.Limits(max_connections=5)
            )
        return self._clients[provider_id]

    def _get_local_config(self, provider_id: str) -> dict:
        config = self.persistence.config
        local = config.local_providers.get(provider_id)
        if not local:
            raise HTTPException(404, f"Local provider '{provider_id}' not configured")
        info = LOCAL_PROVIDERS.get(provider_id, {})
        return {
            **info,
            "base_url": local.base_url,
            "format": info.get("format", "openai"),
        }

    async def list_models(self, provider_id: str) -> List[ModelInfo]:
        info = self._get_local_config(provider_id)
        client = self._get_client(provider_id)
        fmt = info.get("format", "openai")
        endpoint = info.get("models_endpoint", "/v1/models")
        url = f"{info['base_url']}{endpoint}"

        try:
            resp = await client.get(url, timeout=5.0)
            resp.raise_for_status()
            data = resp.json()
        except Exception as e:
            disk_models = []
            for entry in scan_local_gguf_library():
                quant_bits = entry.get("quant_bits")
                disk_models.append(ModelInfo(
                    id=entry["id"],
                    name=entry["label"],
                    provider=provider_id,
                    owned_by=entry.get("repo_id") or entry["folder"],
                    quantization=str(quant_bits or entry.get("precision") or ""),
                    quant_category=None,
                    size_gb=round(float(entry.get("size_bytes", 0)) / (1024**3), 2) if entry.get("size_bytes") else None,
                    is_gguf=True,
                    is_local=True,
                    capabilities=entry.get("capabilities", ["streaming"]),
                    modified_at=None,
                ))
            return disk_models

        models = []
        if fmt == "openai":
            raw = data.get("data", [])
            for m in raw:
                mid = m.get("id", "")
                quant, cat = self._detect_gguf_quant(mid)
                models.append(ModelInfo(
                    id=mid,
                    name=m.get("id", mid),
                    provider=provider_id,
                    owned_by=info.get("name", provider_id),
                    quantization=quant,
                    quant_category=cat,
                    is_gguf=True,
                    is_local=True,
                    capabilities=["chat", "streaming", "tools"],
                    modified_at=m.get("modified_at") or m.get("last_modified"),
                ))
        elif fmt == "ollama":
            raw = data.get("models", [])
            for m in raw:
                name = m.get("name", m.get("model", ""))
                size = m.get("size", 0)
                quant, cat = self._detect_gguf_quant(name)
                models.append(ModelInfo(
                    id=name,
                    name=name,
                    provider=provider_id,
                    owned_by=info.get("name", provider_id),
                    quantization=quant,
                    quant_category=cat,
                    size_gb=round(size / (1024**3), 2) if size else None,
                    is_gguf=True,
                    is_local=True,
                    capabilities=["chat", "streaming", "tools"],
                    modified_at=m.get("modified_at"),
                ))
        elif fmt == "kobold":
            name = data.get("result", "")
            if name:
                quant, cat = self._detect_gguf_quant(name)
                models.append(ModelInfo(
                    id=name,
                    name=name,
                    provider=provider_id,
                    owned_by=info.get("name", provider_id),
                    quantization=quant,
                    quant_category=cat,
                    is_gguf=True,
                    is_local=True,
                    capabilities=["chat", "streaming"],
                ))
        return models

    def _detect_gguf_quant(self, model_id: str) -> Tuple[Optional[str], Optional[str]]:
        match = QUANT_PATTERN.search(model_id)
        if match:
            quant = match.group(1).upper()
            for cat, quants in GGUF_QUANTIZATIONS.items():
                if quant in quants:
                    return quant, cat
            return quant, "Unknown"
        return None, None

    async def test_connection(self, provider_id: str) -> Tuple[bool, str, List[str]]:
        try:
            models = await self.list_models(provider_id)
            return True, "", [m.id for m in models]
        except Exception as e:
            return False, str(e), []

    async def chat_completion(
        self,
        provider_id: str,
        model: str,
        messages: List[dict],
        params: dict,
        tools: Optional[List[dict]] = None,
        tool_choice: Optional[Union[str, dict]] = None,
        stream: bool = False,
        ) -> AsyncGenerator[str, None] | dict:
        if provider_id == "__native__":
            return await self._chat_native(model, messages, params, tools, tool_choice, stream)
        info = self._get_local_config(provider_id)
        fmt = info.get("format", "openai")

        if fmt == "openai":
            return await self._chat_openai_compatible(info, model, messages,
                                                      params, tools, tool_choice,
                                                      stream, provider_id)
        elif fmt == "ollama":
            return await self._chat_ollama(info, model, messages, params,
                                           tools, stream, provider_id)
        elif fmt == "kobold":
            return await self._chat_kobold(info, model, messages, params,
                                           stream, provider_id)
        else:
            raise HTTPException(400, f"Unsupported local format: {fmt}")

    async def _chat_native(
        self,
        model: str,
        messages: List[dict],
        params: dict,
        tools: Optional[List[dict]] = None,
        tool_choice: Optional[Union[str, dict]] = None,
        stream: bool = False,
    ) -> AsyncGenerator[str, None] | dict:
        messages = fold_system_messages_into_user(messages)
        if stream:
            return await NATIVE_GGUF_RUNTIME.chat_completion(messages, params, tools, tool_choice, stream=True)
        return await NATIVE_GGUF_RUNTIME.chat_completion(messages, params, tools, tool_choice, stream=False)

    async def _chat_openai_compatible(self, info, model, messages, params,
                                       tools, tool_choice, stream, provider_id):
        client = self._get_client(provider_id)
        url = f"{info['base_url']}{info['chat_endpoint']}"

        body: dict = {
            "model": model,
            "messages": messages,
            "stream": stream,
        }
        for p in ["temperature", "top_p", "max_tokens", "frequency_penalty",
                   "presence_penalty", "stop", "seed"]:
            if p in params and params[p] is not None:
                body[p] = params[p]
        if "top_k" in params:
            body["top_k"] = params["top_k"]
        if "repetition_penalty" in params:
            body["repetition_penalty"] = params["repetition_penalty"]
        if tools:
            body["tools"] = tools
        if tool_choice:
            body["tool_choice"] = tool_choice

        if stream:
            return self._stream_openai_compatible(client, url, body)
        else:
            resp = await client.post(url, json=body, timeout=1800)
            resp.raise_for_status()
            return resp.json()

    async def _stream_openai_compatible(self, client, url, body):
        async with client.stream("POST", url, json=body, timeout=1800) as resp:
            async for line in resp.aiter_lines():
                line = line.strip()
                if not line:
                    continue
                if line.startswith("data: "):
                    data = line[6:]
                    if data.strip() == "[DONE]":
                        yield "data: [DONE]\n\n"
                        break
                    try:
                        yield f"data: {data}\n\n"
                    except Exception:
                        continue
                else:
                    try:
                        yield f"data: {line}\n\n"
                    except Exception:
                        continue

    async def _chat_ollama(self, info, model, messages, params,
                           tools, stream, provider_id):
        client = self._get_client(provider_id)
        url = f"{info['base_url']}{info['chat_endpoint']}"

        body: dict = {
            "model": model,
            "messages": messages,
            "stream": stream,
            "keep_alive": -1,
        }
        opts = {}
        for p in ["temperature", "top_p", "top_k", "num_predict"]:
            if p in params:
                opts[p] = params[p]
        if "max_tokens" in params:
            opts["num_predict"] = params["max_tokens"]
        if "repetition_penalty" in params:
            opts["repeat_penalty"] = params["repetition_penalty"]
        if "stop" in params:
            opts["stop"] = params["stop"]
        if opts:
            body["options"] = opts
        if tools:
            ollama_tools = []
            for t in tools:
                if t.get("type") == "function":
                    ollama_tools.append({
                        "type": "function",
                        "function": {
                            "name": t["function"]["name"],
                            "description": t["function"].get("description", ""),
                            "parameters": t["function"].get("parameters", {}),
                        }
                    })
            if ollama_tools:
                body["tools"] = ollama_tools

        if stream:
            return self._stream_ollama(client, url, body, model)
        else:
            resp = await client.post(url, json=body, timeout=1800)
            resp.raise_for_status()
            return resp.json()

    async def _stream_ollama(self, client, url, body, model):
        async with client.stream("POST", url, json=body, timeout=1800) as resp:
            buffer = ""
            async for chunk in resp.aiter_text():
                buffer += chunk
                while "\n" in buffer:
                    line, buffer = buffer.split("\n", 1)
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        event = json.loads(line)
                        msg = event.get("message", {})
                        content = msg.get("content", "")
                        if content:
                            chunk_data = {
                                "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
                                "object": "chat.completion.chunk",
                                "created": int(time.time()),
                                "model": model,
                                "choices": [{
                                    "index": 0,
                                    "delta": {"content": content},
                                    "finish_reason": None
                                }]
                            }
                            yield f"data: {json.dumps(chunk_data)}\n\n"
                        if event.get("done"):
                            # Handle tool calls in final message
                            if msg.get("tool_calls"):
                                tc_chunk = {
                                    "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
                                    "object": "chat.completion.chunk",
                                    "created": int(time.time()),
                                    "model": model,
                                    "choices": [{
                                        "index": 0,
                                        "delta": {"tool_calls": msg["tool_calls"]},
                                        "finish_reason": "tool_calls"
                                    }]
                                }
                                yield f"data: {json.dumps(tc_chunk)}\n\n"
                            else:
                                final_chunk = {
                                    "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
                                    "object": "chat.completion.chunk",
                                    "created": int(time.time()),
                                    "model": model,
                                    "choices": [{
                                        "index": 0, "delta": {},
                                        "finish_reason": "stop"
                                    }]
                                }
                                yield f"data: {json.dumps(final_chunk)}\n\n"
                            yield "data: [DONE]\n\n"
                            break
                    except json.JSONDecodeError:
                        continue

    async def _chat_kobold(self, info, model, messages, params, stream, provider_id):
        client = self._get_client(provider_id)
        url = f"{info['base_url']}{info['chat_endpoint']}"

        prompt = ""
        for m in messages:
            if m["role"] == "system":
                prompt += f"### System:\n{m.get('content', '')}\n\n"
            elif m["role"] == "user":
                prompt += f"### User:\n{m.get('content', '')}\n\n"
            elif m["role"] == "assistant":
                prompt += f"### Assistant:\n{m.get('content', '')}\n\n"
        prompt += "### Assistant:\n"

        body = {
            "prompt": prompt,
            "max_length": params.get("max_tokens", 512),
            "temperature": params.get("temperature", 0.7),
            "top_p": params.get("top_p", 0.9),
            "top_k": params.get("top_k", 40),
            "rep_pen": params.get("repetition_penalty", 1.1),
        }

        if stream:
            return self._stream_kobold(client, url, body, model)
        else:
            resp = await client.post(url, json=body, timeout=1800)
            resp.raise_for_status()
            data = resp.json()
            results = data.get("results", [])
            text = results[0].get("text", "") if results else ""
            return {
                "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
                "object": "chat.completion",
                "created": int(time.time()),
                "model": model,
                "choices": [{
                    "index": 0,
                    "message": {"role": "assistant", "content": text},
                    "finish_reason": "stop"
                }],
                "usage": {"prompt_tokens": 0, "completion_tokens": 0, "total_tokens": 0}
            }

    async def _stream_kobold(self, client, url, body, model):
        async with client.stream("POST", url, json=body, timeout=1800) as resp:
            async for line in resp.aiter_lines():
                line = line.strip()
                if not line:
                    continue
                try:
                    event = json.loads(line)
                    token = event.get("token", {})
                    text = token.get("text", "")
                    if text:
                        chunk_data = {
                            "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
                            "object": "chat.completion.chunk",
                            "created": int(time.time()),
                            "model": model,
                            "choices": [{
                                "index": 0,
                                "delta": {"content": text},
                                "finish_reason": None
                            }]
                        }
                        yield f"data: {json.dumps(chunk_data)}\n\n"
                    if event.get("stop"):
                        yield "data: [DONE]\n\n"
                        break
                except json.JSONDecodeError:
                    continue

    async def close(self):
        for client in self._clients.values():
            await client.aclose()
        self._clients.clear()


