# SECTION 8: MCP CLIENT & MANAGER
# â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

@dataclass
class MCPConnection:
    """Represents a live MCP server connection."""
    name: str
    config: MCPServerConfig
    transport: MCPTransportType
    connected: bool = False
    process: Optional[asyncio.subprocess.Process] = None
    sse_session: Optional[httpx.AsyncClient] = None
    sse_url: Optional[str] = None
    tools: List[MCPToolDef] = field(default_factory=list)
    error: Optional[str] = None
    connected_at: Optional[str] = None
    _request_id: int = 0
    _pending: Dict[int, asyncio.Future] = field(default_factory=dict)
    _read_task: Optional[asyncio.Task] = None
    _lock: asyncio.Lock = field(default_factory=asyncio.Lock)

    def next_id(self) -> int:
        self._request_id += 1
        return self._request_id


class MCPManager:
    """
    Full MCP (Model Context Protocol) manager.
    Supports stdio and SSE transports, compatible with LM Studio config format.
    """

    def __init__(self, persistence: PersistenceManager):
        self.persistence = persistence
        self.connections: Dict[str, MCPConnection] = {}
        self._lock = asyncio.Lock()

    async def initialize(self):
        """Load saved servers and auto-connect enabled ones."""
        servers = self.persistence.mcp_servers
        for name, config in servers.items():
            self.connections[name] = MCPConnection(
                name=name, config=config, transport=config.transport
            )
        if self.persistence.config.mcp_auto_connect:
            for name, conn in self.connections.items():
                if conn.config.auto_connect and conn.config.enabled:
                    try:
                        await self.connect(name)
                    except Exception as e:
                        logger.error(f"Auto-connect {name} failed: {e}")
                        conn.error = str(e)

    async def add_server(self, name: str, config: MCPServerConfig):
        async with self._lock:
            self.connections[name] = MCPConnection(
                name=name, config=config, transport=config.transport
            )
            self.persistence.mcp_servers[name] = config
            self.persistence.save_mcp_config()

    async def remove_server(self, name: str):
        async with self._lock:
            conn = self.connections.pop(name, None)
            if conn:
                await self._disconnect(conn)
            self.persistence.mcp_servers.pop(name, None)
            self.persistence.save_mcp_config()

    async def connect(self, name: str):
        async with self._lock:
            conn = self.connections.get(name)
            if not conn:
                raise HTTPException(404, f"MCP server '{name}' not found")
            if conn.connected:
                return

            if conn.transport == MCPTransportType.STDIO:
                await self._connect_stdio(conn)
            elif conn.transport == MCPTransportType.SSE:
                await self._connect_sse(conn)

    async def _connect_stdio(self, conn: MCPConnection):
        """Connect to MCP server via stdio (subprocess)."""
        config = conn.config
        if not config.command:
            raise ValueError(f"Missing command for stdio server '{conn.name}'")

        cmd = [config.command] + config.args
        env = {**os.environ, **config.env}

        try:
            process = await asyncio.create_subprocess_exec(
                *cmd,
                stdin=asyncio.subprocess.PIPE,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                env=env,
                cwd=config.cwd or None,
            )
        except Exception as e:
            conn.error = f"Failed to start process: {e}"
            raise

        conn.process = process
        conn._read_task = asyncio.create_task(
            self._read_stdio_loop(conn), name=f"mcp-read-{conn.name}"
        )

        # Initialize handshake
        try:
            init_result = await self._send_request(conn, "initialize", {
                "protocolVersion": "2024-11-05",
                "capabilities": {
                    "roots": {"listChanged": True},
                },
                "clientInfo": {
                    "name": APP_NAME,
                    "version": APP_VERSION,
                },
            }, timeout=15)

            # Send initialized notification
            await self._send_notification(conn, "notifications/initialized", {})

            conn.connected = True
            conn.connected_at = datetime.now(timezone.utc).isoformat()
            conn.error = None

            # Fetch tools
            if init_result.get("capabilities", {}).get("tools"):
                await self._refresh_tools(conn)

            # Update config
            conn.config.enabled = True
            self.persistence.mcp_servers[conn.name] = conn.config
            self.persistence.save_mcp_config()

            logger.info(f"MCP server '{conn.name}' connected (stdio, pid={process.pid})")

        except Exception as e:
            conn.error = str(e)
            if process:
                try:
                    process.kill()
                except Exception:
                    pass
            if conn._read_task:
                conn._read_task.cancel()
            conn.process = None
            raise

    async def _connect_sse(self, conn: MCPConnection):
        """Connect to MCP server via SSE (HTTP)."""
        config = conn.config
        if not config.url:
            raise ValueError(f"Missing URL for SSE server '{conn.name}'")

        try:
            client = httpx.AsyncClient(timeout=httpx.Timeout(30.0))
            resp = await client.get(config.url)
            resp.raise_for_status()
            sse_url = config.url

            # Parse SSE to get message endpoint
            message_url = config.url.replace("/sse", "/messages")
            if not message_url.endswith("/messages"):
                message_url = config.url.rsplit("/", 1)[0] + "/messages"

            conn.sse_session = client
            conn.sse_url = sse_url

            # Initialize via POST
            init_result = await self._send_sse_request(conn, message_url, "initialize", {
                "protocolVersion": "2024-11-05",
                "capabilities": {},
                "clientInfo": {"name": APP_NAME, "version": APP_VERSION},
            }, timeout=15)

            await self._send_sse_notification(conn, message_url, "notifications/initialized", {})

            conn.connected = True
            conn.connected_at = datetime.now(timezone.utc).isoformat()
            conn.error = None

            if init_result.get("capabilities", {}).get("tools"):
                await self._refresh_tools(conn)

            logger.info(f"MCP server '{conn.name}' connected (SSE, url={config.url})")

        except Exception as e:
            conn.error = str(e)
            if conn.sse_session:
                await conn.sse_session.aclose()
            conn.sse_session = None
            raise

    async def _read_stdio_loop(self, conn: MCPConnection):
        """Continuously read from MCP process stdout."""
        try:
            while conn.process and conn.process.stdout:
                line = await conn.process.stdout.readline()
                if not line:
                    break
                try:
                    msg = json.loads(line.decode("utf-8").strip())
                    await self._handle_message(conn, msg)
                except json.JSONDecodeError:
                    pass
                except Exception as e:
                    logger.debug(f"MCP read error for {conn.name}: {e}")
        except asyncio.CancelledError:
            pass
        except Exception as e:
            logger.error(f"MCP stdio read loop error for {conn.name}: {e}")
        finally:
            if conn.connected:
                conn.connected = False
                conn.error = "Process terminated"
                conn.process = None

    async def _handle_message(self, conn: MCPConnection, msg: dict):
        """Handle incoming JSON-RPC message."""
        if "id" in msg and msg["id"] in conn._pending:
            future = conn._pending.pop(msg["id"])
            if not future.done():
                if "error" in msg:
                    future.set_exception(Exception(msg["error"].get("message", "MCP error")))
                else:
                    future.set_result(msg.get("result", {}))

    async def _send_request(self, conn: MCPConnection, method: str,
                            params: dict, timeout: float = 30) -> dict:
        """Send JSON-RPC request and wait for response."""
        request_id = conn.next_id()
        msg = {
            "jsonrpc": "2.0",
            "id": request_id,
            "method": method,
            "params": params,
        }

        async with conn._lock:
            if conn.process and conn.process.stdin:
                data = json.dumps(msg) + "\n"
                conn.process.stdin.write(data.encode("utf-8"))
                await conn.process.stdin.drain()
            else:
                raise ConnectionError(f"Not connected to '{conn.name}'")

        future: asyncio.Future = asyncio.get_event_loop().create_future()
        conn._pending[request_id] = future

        try:
            return await asyncio.wait_for(future, timeout=timeout)
        except asyncio.TimeoutError:
            conn._pending.pop(request_id, None)
            raise TimeoutError(f"MCP request '{method}' timed out")

    async def _send_notification(self, conn: MCPConnection, method: str, params: dict):
        """Send JSON-RPC notification (no response expected)."""
        msg = {
            "jsonrpc": "2.0",
            "method": method,
            "params": params,
        }
        async with conn._lock:
            if conn.process and conn.process.stdin:
                data = json.dumps(msg) + "\n"
                conn.process.stdin.write(data.encode("utf-8"))
                await conn.process.stdin.drain()

    async def _send_sse_request(self, conn: MCPConnection, message_url: str,
                                 method: str, params: dict,
                                 timeout: float = 30) -> dict:
        """Send JSON-RPC request via SSE POST endpoint."""
        request_id = conn.next_id()
        msg = {
            "jsonrpc": "2.0",
            "id": request_id,
            "method": method,
            "params": params,
        }
        if conn.sse_session:
            resp = await conn.sse_session.post(
                message_url, json=msg, timeout=timeout
            )
            resp.raise_for_status()
            data = resp.json()
            if "error" in data:
                raise Exception(data["error"].get("message", "MCP error"))
            return data.get("result", {})
        raise ConnectionError(f"SSE not connected for '{conn.name}'")

    async def _send_sse_notification(self, conn: MCPConnection, message_url: str,
                                      method: str, params: dict):
        """Send JSON-RPC notification via SSE POST endpoint."""
        msg = {
            "jsonrpc": "2.0",
            "method": method,
            "params": params,
        }
        if conn.sse_session:
            try:
                await conn.sse_session.post(message_url, json=msg, timeout=5)
            except Exception:
                pass

    async def _refresh_tools(self, conn: MCPConnection):
        """Fetch tool list from connected MCP server."""
        try:
            if conn.transport == MCPTransportType.STDIO:
                result = await self._send_request(conn, "tools/list", {}, timeout=10)
            elif conn.transport == MCPTransportType.SSE:
                config = conn.config
                message_url = config.url.replace("/sse", "/messages")
                if not message_url.endswith("/messages"):
                    message_url = config.url.rsplit("/", 1)[0] + "/messages"
                result = await self._send_sse_request(conn, message_url, "tools/list", {}, timeout=10)
            else:
                return

            tools = []
            for t in result.get("tools", []):
                tools.append(MCPToolDef(
                    name=t.get("name", ""),
                    description=t.get("description", ""),
                    input_schema=t.get("inputSchema", {}),
                ))
            conn.tools = tools
            logger.info(f"MCP '{conn.name}': {len(tools)} tools loaded")
        except Exception as e:
            logger.error(f"Failed to refresh tools for '{conn.name}': {e}")

    async def disconnect(self, name: str):
        async with self._lock:
            conn = self.connections.get(name)
            if conn:
                await self._disconnect(conn)

    async def _disconnect(self, conn: MCPConnection):
        was_connected = conn.connected
        conn.connected = False
        conn.error = None

        if conn._read_task:
            conn._read_task.cancel()
            try:
                await conn._read_task
            except asyncio.CancelledError:
                pass
            conn._read_task = None

        if conn.process:
            try:
                conn.process.stdin.write(json.dumps({
                    "jsonrpc": "2.0", "method": "shutdown", "params": {}
                }).encode() + b"\n")
                await conn.process.stdin.drain()
                await asyncio.sleep(0.1)
                conn.process.stdin.write(json.dumps({
                    "jsonrpc": "2.0", "method": "exit", "params": {}
                }).encode() + b"\n")
                await conn.process.stdin.drain()
                await asyncio.sleep(0.2)
            except Exception:
                pass
            try:
                conn.process.terminate()
                await asyncio.wait_for(conn.process.wait(), timeout=3)
            except asyncio.TimeoutError:
                try:
                    conn.process.kill()
                except Exception:
                    pass
            except Exception:
                pass
            conn.process = None

        if conn.sse_session:
            await conn.sse_session.aclose()
            conn.sse_session = None

        conn.tools = []
        if was_connected:
            logger.info(f"MCP server '{conn.name}' disconnected")

    async def call_tool(self, server_name: str, tool_name: str,
                        arguments: dict) -> Any:
        """Execute a tool on a connected MCP server."""
        conn = self.connections.get(server_name)
        if not conn:
            raise HTTPException(404, f"MCP server '{server_name}' not found")
        if not conn.connected:
            raise HTTPException(400, f"MCP server '{server_name}' not connected")

        try:
            if conn.transport == MCPTransportType.STDIO:
                result = await self._send_request(conn, "tools/call", {
                    "name": tool_name,
                    "arguments": arguments,
                }, timeout=120)
            elif conn.transport == MCPTransportType.SSE:
                config = conn.config
                message_url = config.url.replace("/sse", "/messages")
                if not message_url.endswith("/messages"):
                    message_url = config.url.rsplit("/", 1)[0] + "/messages"
                result = await self._send_sse_request(conn, message_url, "tools/call", {
                    "name": tool_name,
                    "arguments": arguments,
                }, timeout=120)
            else:
                raise HTTPException(400, "Unknown transport")

            # Extract text content from result
            content = result.get("content", [])
            text_parts = []
            for c in content:
                if c.get("type") == "text":
                    text_parts.append(c["text"])
                elif c.get("type") == "image":
                    text_parts.append(f"[Image: {c.get('mimeType', 'image')}]")
                else:
                    text_parts.append(json.dumps(c))
            return {
                "content": "\n".join(text_parts),
                "is_error": result.get("isError", False),
                "raw": result,
            }
        except Exception as e:
            return {
                "content": f"Tool execution error: {e}",
                "is_error": True,
                "raw": None,
            }

    def get_all_tools(self) -> List[dict]:
        """Get all tools from all connected servers in OpenAI format."""
        all_tools = []
        for name, conn in self.connections.items():
            if conn.connected:
                for tool in conn.tools:
                    all_tools.append({
                        "type": "function",
                        "function": {
                            "name": tool.name,
                            "description": tool.description,
                            "parameters": tool.input_schema,
                        },
                        "mcp_server": name,
                    })
        return all_tools

    def get_server_status(self) -> List[MCPServerStatus]:
        statuses = []
        for name, conn in self.connections.items():
            statuses.append(MCPServerStatus(
                name=conn.name,
                transport=conn.transport.value,
                connected=conn.connected,
                tools=conn.tools,
                error=conn.error,
                pid=conn.process.pid if conn.process else None,
                connected_at=conn.connected_at,
            ))
        return statuses

    async def shutdown(self):
        for conn in self.connections.values():
            await self._disconnect(conn)
        self.connections.clear()


