    async def _exec_python_tool(self, args: dict) -> dict:
        """Python code execution tool."""
        import shutil as _shutil
        python_cmd = "python3" if _shutil.which("python3") else ("python" if _shutil.which("python") else None)
        if not python_cmd:
            return {"content": "Python is not installed.", "is_error": True}
        
        code = args.get("code", "")
        file_path = args.get("file")
        module = args.get("module")
        
        python_args = []
        
        if code:
            python_args.extend(["-c", code])
        elif file_path:
            python_args.append(file_path)
        elif module:
            python_args.extend(["-m", module])
        else:
            return {"content": "Provide either 'code', 'file', or 'module' parameter.", "is_error": True}
        
        # Add Python options
        if args.get("verbose"):
            python_args.append("-v")
        if args.get("interactive"):
            python_args.append("-i")
        if args.get("optimize"):
            opt_level = min(int(args.get("optimize")), 2)
            python_args.append(f"-O{opt_level}" if opt_level > 1 else "-O")
        
        # Additional arguments
        script_args = args.get("args", [])
        if isinstance(script_args, list):
            python_args.extend(script_args)
        
        working_dir = args.get("cwd") or str(WORKSPACE_DIR)
        
        try:
            process = await asyncio.create_subprocess_exec(
                python_cmd, *python_args,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                cwd=working_dir,
                env={**os.environ, "TERM": "dumb", "PYTHONUNBUFFERED": "1"}
            )
            stdout, stderr = await asyncio.wait_for(process.communicate(), timeout=int(args.get("timeout", 120)))
            
            out_str = stdout.decode('utf-8', errors='replace').strip()
            err_str = stderr.decode('utf-8', errors='replace').strip()
            
            output = ""
            if out_str:
                output += f"[STDOUT]\\n{out_str}\\n"
            if err_str:
                output += f"[STDERR]\\n{err_str}\\n"
            if not output:
                output = "Python executed successfully with no output."
            
            output += f"\\n[Exit Code: {process.returncode}]"
            
            if len(output) > 50000:
                output = output[:50000] + "\\n...[Output truncated]"
            
            return {"content": output, "is_error": process.returncode != 0}
        except asyncio.TimeoutError:
            return {"content": "Python execution timed out.", "is_error": True}
        except Exception as e:
            return {"content": f"Python error: {e}", "is_error": True}
    
    async def _exec_sed_tool(self, args: dict) -> dict:
        """Stream editor (sed) operations."""
        import shutil as _shutil
        sed_cmd = "sed" if _shutil.which("sed") else None
        if not sed_cmd:
            return {"content": "sed is not available on this system.", "is_error": True}
        
        sed_args = []
        
        expression = args.get("expression", "") or args.get("expr", "")
        if expression:
            sed_args.extend(["-e", expression])
        # Common patterns
        substitute = args.get("substitute")
        if substitute:
            pattern = substitute.get("pattern", "")
            replacement = substitute.get("replacement", "")
            flags = substitute.get("flags", "g")
            sed_args.extend(["-e", f"s/{pattern}/{replacement}/{flags}"])
        delete = args.get("delete")
        if delete:
            sed_args.extend(["-e", f"/{delete}/d"])
        insert = args.get("insert")
        if insert:
            line_num = insert.get("line", "")
            text = insert.get("text", "")
            sed_args.extend([f"{line_num}a\\\\\\n{text}"])
        # File operations
        in_place = args.get("in_place", False)
        if in_place:
            sed_args.append("-i")
            if args.get("backup"):
                sed_args.append(f".{args.get('backup')}" if isinstance(args.get('backup'), str) else ".bak")
        extended_regex = args.get("extended", True)
        if extended_regex:
            sed_args.append("-E")
        silent = args.get("silent", False)
        if silent:
            sed_args.append("-n")
        file_path = args.get("path") or args.get("file", "")
        if file_path:
            sed_args.append(file_path)
        # Input text alternative
        input_text = args.get("input", "")
        try:
            if input_text and not file_path:
                process = await asyncio.create_subprocess_exec(
                    sed_cmd, *sed_args,
                    stdin=asyncio.subprocess.PIPE,
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE,
                    cwd=str(WORKSPACE_DIR),
                    env={**os.environ, "TERM": "dumb"}
                )
                stdout, stderr = await process.communicate(input=input_text.encode())
            else:
                process = await asyncio.create_subprocess_exec(
                    sed_cmd, *sed_args,
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE,
                    cwd=str(WORKSPACE_DIR),
                    env={**os.environ, "TERM": "dumb"}
                )
                stdout, stderr = await asyncio.wait_for(process.communicate(), timeout=60)
            out_str = stdout.decode('utf-8', errors='replace').strip()
            err_str = stderr.decode('utf-8', errors='replace').strip()
            output = ""
            if out_str:
                output += f"{out_str}\\n"
            if err_str:
                output += f"[STDERR] {err_str}\\n"
            if not output:
                output = "sed completed."
            return {"content": output, "is_error": process.returncode != 0}
        except asyncio.TimeoutError:
            return {"content": "sed command timed out.", "is_error": True}
        except Exception as e:
            return {"content": f"sed error: {e}", "is_error": True}
