    @router.get("/api/models/status")
    async def api_models_status():
        # Minimal status expected by the desktop frontend
        local_models = [
            {
                "id": entry["id"],
                "label": entry["label"],
                "present": True,
                "loaded": entry["id"] == MODEL_LOAD_STATE.get("active_model"),
                "model_type": entry.get("model_type") or "causal",
                "params": entry.get("params") or "",
                "quant_bits": entry.get("quant_bits"),
                "purpose": entry.get("purpose"),
                "folder": entry.get("folder"),
                "size_bytes": entry.get("size_bytes", 0),
                "local_bytes": entry.get("local_bytes", 0),
                "capabilities": ["vision", "chat", "streaming"] if "vision" in entry.get("folder", "").lower() or "vl" in entry.get("folder", "").lower() else ["chat", "streaming"],
                "download": ACTIVE_DOWNLOADS.get(entry["id"]),
            }
            for entry in scan_local_gguf_library()
        ]
        scanned_ids = {m["id"] for m in local_models}
        for d_id, d_info in ACTIVE_DOWNLOADS.items():
            if d_id not in scanned_ids:
                local_models.append({
                    "id": d_id,
                    "label": d_info.get("label") or d_id,
                    "present": False,
                    "loaded": False,
                    "model_type": "causal",
                    "params": "",
                    "quant_bits": None,
                    "purpose": "chat",
                    "folder": d_info.get("repo_id"),
                    "size_bytes": d_info.get("total_bytes", 0),
                    "local_bytes": d_info.get("downloaded_bytes", 0),
                    "download": d_info,
                })
        return {
            "status": "idle",
            "active_downloads": ACTIVE_DOWNLOADS,
            "loaded_models": [persistence.config.inference.default_model] if persistence.config.inference.default_model else [],
            "hf_token_set": HF_TOKEN_FILE.exists(),
            "models": local_models,
        }

