    @router.post("/api/files/preview", response_model=AttachmentPreviewResponse)
    async def preview_attachment(body: AttachmentPreviewRequest):
        safe_name = Path(body.name or "attachment").name
        raw_bytes = base64.b64decode(body.content_base64 or "")
        if not raw_bytes:
            raise HTTPException(400, "Attachment content is empty")

        ext = Path(safe_name).suffix.lower().lstrip(".") or "txt"
        tmp_path: Optional[Path] = None
        try:
            with tempfile.NamedTemporaryFile(suffix=f".{ext}", delete=False) as tmp:
                tmp.write(raw_bytes)
                tmp_path = Path(tmp.name)
            return rag_service.build_attachment_preview(
                tmp_path,
                ext,
                safe_name,
                size_bytes=body.size or len(raw_bytes),
            )
        finally:
            if tmp_path is not None:
                try:
                    tmp_path.unlink(missing_ok=True)
                except Exception:
                    pass

