    @router.post("/api/providers/connect")
    async def connect_provider(body: dict):
        """Connect to a cloud provider by testing API key and fetching models."""
        provider_id = str(body.get("provider_id") or body.get("provider") or "").strip()
        api_key = body.get("api_key", "")
        base_url = body.get("base_url")
        model = body.get("model")

        if not provider_id:
            raise HTTPException(400, "provider_id is required")
        if provider_id not in CLOUD_PROVIDERS:
            raise HTTPException(400, f"Unknown provider: {provider_id}")

        config = persistence.config
        conn = config.cloud_providers.get(provider_id, ProviderConnection(
            provider_id=provider_id,
            name=CLOUD_PROVIDERS[provider_id]["name"],
        ))
        conn.api_key = api_key
        if base_url:
            conn.base_url = base_url
        if isinstance(model, str) and model.strip():
            conn.model = model.strip()

        # Test connection
        success, error, models = await cloud_engine.test_connection(provider_id)

        conn.connected = success
        conn.last_tested = datetime.now(timezone.utc).isoformat()
        conn.models = models
        conn.error = error if not success else None

        config.cloud_providers[provider_id] = conn
        persistence.config = config

        if success:
            return {
                "status": "connected",
                "provider_id": provider_id,
                "provider": provider_id,
                "model_count": len(models),
                "models": models[:20],  # Return first 20
                "configured": True,
                "api_key_set": bool(api_key),
                "config": {
                    "provider": provider_id,
                    "api_key": api_key,
                    "base_url": conn.base_url,
                    "model": conn.model,
                },
                "saved": {pid: p.model_dump() for pid, p in config.cloud_providers.items()},
            }
        else:
            raise HTTPException(400, f"Connection failed: {error}")

    @router.post("/api/providers/disconnect")
    @router.delete("/api/providers/{provider_id}")
    async def disconnect_provider(provider_id: str = "", body: Optional[dict] = None):
        if body and not provider_id:
            provider_id = str(body.get("provider_id") or body.get("provider") or "").strip()
        config = persistence.config
        if provider_id in config.cloud_providers:
            conn = config.cloud_providers[provider_id]
            conn.connected = False
            conn.api_key = None
            conn.models = []
            conn.model = None
            config.cloud_providers[provider_id] = conn
            persistence.config = config
        return {"status": "disconnected", "provider": provider_id, "configured": provider_id in config.cloud_providers, "disconnected": True}

