    # ---------------- OAuth Routes ----------------
    oauth_states = {}
    # Was a disconnected local dict before -- tokens saved here were never
    # visible to ChatService._execute_builtin_tool, which is why the Gmail
    # tool call always failed authentication regardless of what the OAuth
    # flow returned. Now both sides share the exact same dict.
    oauth_tokens = chat_service.oauth_tokens

    import secrets
    import urllib.parse
    import requests
    from fastapi.responses import HTMLResponse, RedirectResponse
    import os

    GITHUB_CLIENT_ID = os.getenv("GITHUB_CLIENT_ID", "")
    GITHUB_CLIENT_SECRET = os.getenv("GITHUB_CLIENT_SECRET", "")
    GOOGLE_CLIENT_ID = os.getenv("GOOGLE_CLIENT_ID", "")
    GOOGLE_CLIENT_SECRET = os.getenv("GOOGLE_CLIENT_SECRET", "")

    @router.get("/api/oauth/{app_id}/login")
    async def oauth_login(app_id: str):
        state = secrets.token_urlsafe(16)
        oauth_states[state] = app_id
        
        if app_id == "github":
            if not GITHUB_CLIENT_ID:
                return HTMLResponse("GitHub Client ID not configured. Please add GITHUB_CLIENT_ID to your environment variables.", status_code=500)
            url = f"https://github.com/login/oauth/authorize?client_id={GITHUB_CLIENT_ID}&state={state}&scope=repo,read:user"
            return RedirectResponse(url)
        elif app_id in ["gmail", "gdrive"]:
            if not GOOGLE_CLIENT_ID:
                return HTMLResponse("Google Client ID not configured. Please add GOOGLE_CLIENT_ID to your environment variables.", status_code=500)
            scopes = (
                "https://www.googleapis.com/auth/gmail.readonly "
                "https://www.googleapis.com/auth/gmail.send "
                "https://www.googleapis.com/auth/drive.readonly"
            )
            redirect_uri = urllib.parse.quote("http://localhost:8000/api/oauth/google/callback")
            url = f"https://accounts.google.com/o/oauth2/v2/auth?client_id={GOOGLE_CLIENT_ID}&redirect_uri={redirect_uri}&response_type=code&scope={urllib.parse.quote(scopes)}&state={state}&access_type=offline&prompt=consent"
            return RedirectResponse(url)
        else:
            return HTMLResponse(f"OAuth not supported for {app_id}", status_code=400)

    @router.get("/api/oauth/{provider}/callback")
    async def oauth_callback(provider: str, code: str = None, state: str = None, error: str = None):
        if error:
            return HTMLResponse(f"OAuth Error: {error}", status_code=400)
        
        app_id = oauth_states.get(state)
            
        try:
            token_data = None
            if provider == "github":
                resp = requests.post(
                    "https://github.com/login/oauth/access_token",
                    data={"client_id": GITHUB_CLIENT_ID, "client_secret": GITHUB_CLIENT_SECRET, "code": code},
                    headers={"Accept": "application/json"}
                )
                resp.raise_for_status()
                token_data = resp.json().get("access_token")
            elif provider == "google":
                resp = requests.post(
                    "https://oauth2.googleapis.com/token",
                    data={
                        "client_id": GOOGLE_CLIENT_ID,
                        "client_secret": GOOGLE_CLIENT_SECRET,
                        "code": code,
                        "grant_type": "authorization_code",
                        "redirect_uri": "http://localhost:8000/api/oauth/google/callback"
                    }
                )
                resp.raise_for_status()
                google_json = resp.json()
                token_data = google_json.get("access_token")
                google_refresh_token = google_json.get("refresh_token")
                google_expires_in = google_json.get("expires_in", 3600)
            
            if token_data:
                app_key = app_id if app_id else provider
                if provider == "google":
                    previous_google = oauth_tokens.get(app_key) or oauth_tokens.get("google") or {}
                    google_entry = {
                        "access_token": token_data,
                        "refresh_token": google_refresh_token or previous_google.get("refresh_token"),
                        "expires_at": time.time() + int(google_expires_in) - 60,
                    }
                    oauth_tokens[app_key] = google_entry
                    oauth_tokens["google"] = google_entry
                    if app_key in ["gmail", "gdrive"]:
                        oauth_tokens[app_key] = google_entry
                else:
                    oauth_tokens[app_key] = {"access_token": token_data, "refresh_token": None, "expires_at": None}
                chat_service._save_oauth_tokens()
                
                return HTMLResponse(
                    "<html><head><style>body { font-family: sans-serif; display: flex; justify-content: center; align-items: center; height: 100vh; background: #111; color: #fff; margin: 0; }</style></head><body>"
                    "<div style='text-align: center;'>"
                    "<h2 style='color: #34d399;'>Successfully authenticated!</h2>"
                    "<p style='opacity: 0.7;'>You can close this window and return to MeeraAI.</p>"
                    "</div>"
                    "<script>setTimeout(() => window.close(), 3000);</script>"
                    "</body></html>"
                )
            else:
                return HTMLResponse("Failed to obtain access token", status_code=400)
        except Exception as e:
            return HTMLResponse(f"Exception during token exchange: {e}", status_code=500)

    def _refresh_google_token(entry: dict) -> dict:
        """Exchange a stored refresh_token for a fresh access_token."""
        refresh_token = entry.get("refresh_token")
        if not refresh_token or not GOOGLE_CLIENT_ID or not GOOGLE_CLIENT_SECRET:
            return entry
        try:
            resp = requests.post(
                "https://oauth2.googleapis.com/token",
                data={
                    "client_id": GOOGLE_CLIENT_ID,
                    "client_secret": GOOGLE_CLIENT_SECRET,
                    "refresh_token": refresh_token,
                    "grant_type": "refresh_token",
                },
                timeout=10.0,
            )
            resp.raise_for_status()
            data = resp.json()
            entry["access_token"] = data.get("access_token", entry.get("access_token"))
            entry["expires_at"] = time.time() + int(data.get("expires_in", 3600)) - 60
            chat_service._save_oauth_tokens()
        except Exception as e:
            logger.error(f"Failed to refresh Google OAuth token: {e}")
        return entry

    @router.get("/api/oauth/{app_id}/status")
    async def oauth_status(app_id: str):
        entry = oauth_tokens.get(app_id) or (oauth_tokens.get("google") if app_id in ["gmail", "gdrive"] else None)
        if not entry:
            return {"status": "pending"}

        # Tokens now persist (keyed by app) instead of being popped on first
        # read, and are refreshed transparently once they're close to expiry
        # instead of forcing the user to redo the whole consent flow.
        if entry.get("expires_at") and time.time() > entry["expires_at"]:
            entry = _refresh_google_token(entry)
            oauth_tokens[app_id] = entry
            if app_id != "google":
                oauth_tokens["google"] = entry
            chat_service._save_oauth_tokens()

        if not entry.get("access_token"):
            return {"status": "pending"}

        return {"status": "success", "connected": True}

    @router.post("/api/oauth/{app_id}/disconnect")
    @router.delete("/api/oauth/{app_id}")
    async def oauth_disconnect(app_id: str):
        oauth_tokens.pop(app_id, None)
        if app_id in ["gmail", "gdrive"]:
            other_google_apps = [key for key in ["gmail", "gdrive"] if key != app_id and key in oauth_tokens]
            if not other_google_apps:
                oauth_tokens.pop("google", None)
        chat_service._save_oauth_tokens()
        return {"status": "disconnected", "connected": False}

