# SECTION 15: ENTRY POINT
# â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

app = create_app()

if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description=f"{APP_NAME} v{APP_VERSION}")
    parser.add_argument("--host", default="0.0.0.0", help="Bind host")
    parser.add_argument("--port", type=int, default=8000, help="Bind port")
    parser.add_argument("--reload", action="store_true", help="Enable auto-reload")
    parser.add_argument("--data-dir", default=None, help="Data directory path")
    parser.add_argument("--api", action="store_true",
                        help="Start REST API server (default)")
    parser.add_argument("--log-level", default="INFO",
                       choices=["DEBUG", "INFO", "WARNING", "ERROR"])
    args = parser.parse_args()

    if args.data_dir:
        DATA_DIR = Path(args.data_dir)
        CONFIG_FILE = DATA_DIR / "config.json"
        DB_FILE = DATA_DIR / "conversations.db"
        DOCUMENTS_DIR = DATA_DIR / "rag" / "documents"
        INDEXES_DIR = DATA_DIR / "rag" / "indexes"

    logging.getLogger("Meera").setLevel(getattr(logging, args.log_level))
    logging.getLogger("httpx").setLevel(logging.WARNING)
    logging.getLogger("uvicorn.access").setLevel(logging.WARNING)

    uvicorn.run(
        "backend:app" if args.reload else app,
        host=args.host,
        port=args.port,
        reload=args.reload,
        log_level=args.log_level.lower(),
        timeout_keep_alive=300,
    )
